package com.example.minicommerce.catalog.application;
import com.example.minicommerce.messaging.application.*;import com.example.minicommerce.messaging.config.RabbitTopology;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class ProductCacheInvalidationConsumer{private final ObjectMapper json;private final ProcessedMessageService processed;private final ProductCacheService cache;public ProductCacheInvalidationConsumer(ObjectMapper j,ProcessedMessageService p,ProductCacheService c){json=j;processed=p;cache=c;}@RabbitListener(queues=RabbitTopology.CACHE_Q)@Transactional public void invalidate(String raw)throws Exception{EventEnvelope e=json.readValue(raw,EventEnvelope.class);if(!processed.claim("cache-product-changed",e.eventId()))return;cache.evict(e.payload().get("productId").asLong());}}
